const xml = String($input.first().json.data || $input.first().json.body || '');
const clean = (s) => String(s || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/<[^>]+>/g, '')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/\s+/g, ' ').trim();
const grab = (block, tag) => {
  const m = block.match(new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)<\\/' + tag + '>', 'i'));
  return m ? m[1] : '';
};
const items = [];
for (const block of (xml.match(/<item[\s\S]*?<\/item>/gi) || []).slice(0, 8)) {
  const title = clean(grab(block, 'title'));
  let link = clean(grab(block, 'link')) || clean(grab(block, 'guid'));
  if (!/^https?:\/\//i.test(link)) continue;
  const desc = clean(grab(block, 'description'));
  const dateRaw = clean(grab(block, 'pubDate') || grab(block, 'dc:date'));
  const ts = dateRaw ? Date.parse(dateRaw) : NaN;
  items.push({
    title: title.slice(0, 300),
    link: link.slice(0, 1000),
    description: desc.slice(0, 1000),
    source: 'Ministero dell’Interno',
    published_at: ts && !isNaN(ts) ? new Date(ts).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10)
  });
}
if (!items.length) throw new Error('Nessuna notizia riconosciuta nel feed: formato cambiato?');
return items.map((json) => ({ json }));
